/* Les seules sources chargees sont des agregats proteges. Aucun acces reseau. */
(function(root){
  const pct=v=>v==null?'Non calculable':new Intl.NumberFormat('fr-FR',{style:'percent',maximumFractionDigits:1}).format(v);
  const integer=v=>v==null?'—':new Intl.NumberFormat('fr-FR').format(v);
  function aggregate(rows,year,formation){const selected=rows.filter(r=>r.annee===year&&(formation==='all'||r.formation_id===formation));if(!selected.length)return{state:'absent'};if(selected.some(r=>r.masque))return{state:'masked'};const out={state:'ok'};for(const key of Object.keys(selected[0]))if(!['annee','formation_id','masque'].includes(key))out[key]=selected.reduce((n,r)=>n+(r[key]??0),0);return out;}
  function rate(x,n,d){return x.state==='ok'&&x[d]>0?x[n]/x[d]:null;}
  root.ObsMath={aggregate,rate,pct,integer};
  if(typeof document==='undefined')return;
  const data=root.OBS_DATA,$=s=>document.querySelector(s);let metric='success';
  for(const f of data.formations){const opt=document.createElement('option');opt.value=f.formation_id;opt.textContent=f.libelle_fictif;$('#formation').append(opt);}
  const methods=[
    ['Effectifs inscrits','Nombre d’étudiants distincts dans l’année et la formation sélectionnées.','COUNT DISTINCT étudiant, après application du périmètre','Une inscription principale par personne et année. Ne pas additionner les années pour compter des personnes uniques sur toute la fenêtre.'],
    ['Évolution des inscriptions','Variation relative entre deux années consécutives et comparables.','(N courant − N précédent) / N précédent × 100','Dénominateur nul ou année précédente absente : non calculable. La hausse simulée ne mesure aucune attractivité réelle.'],
    ['Taux de réussite : validation annuelle','Validations connues rapportées à toutes les inscriptions éligibles.','Validations oui / inscriptions éligibles × 100','Les résultats inconnus restent au dénominateur sans devenir des échecs individuels. Lire la couverture et la validation parmi connus. La diplomation terminale utilise un autre dénominateur.'],
    ['Taux de passage','Réinscription au niveau immédiatement supérieur dans la même formation.','Passages / inscriptions de départ non terminales suivables × 100','Les niveaux terminaux sont exclus. La dernière année est censurée pour le devenir futur : un zéro ne doit pas remplacer une observation indisponible.'],
    ['Taux de réorientation','Réinscription dans une autre formation l’année suivante.','Réorientations / cohorte de départ suivable × 100','La cohorte de référence inclut ici les niveaux terminaux. Absence de réinscription ne signifie pas abandon ; sorties documentées et inconnus restent séparés.'],
    ['Taux de participation','Répondants à au moins un item substantiel parmi les invitations délivrées.','Répondants / sollicitations effectivement délivrées × 100','Une inscription par vague. Les invitations non délivrées sont exclues. Décrire les profils des répondants avant toute généralisation.'],
    ['Taux de satisfaction','Notes 4 ou 5 à l’item global, parmi les avis valides de 1 à 5.','Avis 4 ou 5 / avis 1 à 5 × 100','Exclure sans avis et item manquant ; conserver leur décompte. Non-réponse ne signifie pas insatisfaction. Afficher la participation à côté du résultat.'],
    ['Taux d’emploi des diplômés','Emploi parmi les répondants de situation connue à six mois calendaires du diplôme.','Emploi / situations connues, études comprises × 100','L’année sélectionnée est l’année de diplôme. Les diplômés de juillet 2026 n’atteignent pas six mois à la clôture. L’insertion parmi actifs exclut études et inactivité : autre mesure, autre dénominateur.']
  ];
  $('#method-list').innerHTML=methods.map((m,i)=>`<details class="method"><summary>${String(i+1).padStart(2,'0')} &nbsp; ${m[0]}</summary><p>${m[1]}</p><code class="formula">${m[2]}</code><p>${m[3]}</p></details>`).join('');
  function card(label,value,caption,icon='↗',unavailable=false){return `<article class="kpi"><div class="kpi-label">${label}<span class="kpi-icon" aria-hidden="true">${icon}</span></div><div class="kpi-value ${unavailable?'unavailable':''}">${value}</div><p class="kpi-caption">${caption}</p></article>`;}
  function statusText(x){return x.state==='masked'?'Masqué':'Non calculable';}
  function showView(id){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);if(b.dataset.view===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
  document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
  $('#open-methods').addEventListener('click',()=>{showView('methods');$('#methods').scrollIntoView({behavior:'smooth'});});
  function render(){const year=$('#year').value,formation=$('#formation').value,name=formation==='all'?'Toutes les formations':data.formations.find(f=>f.formation_id===formation).libelle_fictif;
    const s=aggregate(data.school,year,formation),e=aggregate(data.survey,year,formation),g=aggregate(data.employment,year,formation),last=year==='2025-2026';
    const previous=aggregate(data.school,`${Number(year.slice(0,4))-1}-${Number(year.slice(5))-1}`,formation),evolution=previous.state==='ok'&&previous.inscrits>0&&s.state==='ok'?(s.inscrits-previous.inscrits)/previous.inscrits:null;
    $('#scope').textContent=year+' · '+name;$('#filter-status').textContent=formation==='all'?'5 formations sélectionnées':'1 formation sélectionnée';
    const success=rate(s,'validations','inscrits'),satisfaction=rate(e,'satisfaits','avis'),employment=rate(g,'emploi','situations_connues'),participation=rate(e,'repondants','sollicites');
    $('#kpis').innerHTML=card('Étudiants inscrits',s.state==='ok'?integer(s.inscrits):statusText(s),evolution==null?'Évolution : année précédente indisponible':`<strong>${evolution>=0?'+':''}${pct(evolution)}</strong> par rapport à l’année précédente`,'◫',s.state!=='ok')+
      card('Validation annuelle',success==null?statusText(s):pct(success),success==null?'Données indisponibles':`${integer(s.validations)} validations / ${integer(s.inscrits)} éligibles`,'✓',success==null)+
      card('Satisfaction',satisfaction==null?statusText(e):pct(satisfaction),satisfaction==null?'Données indisponibles':`${integer(e.satisfaits)} / ${integer(e.avis)} avis · participation ${pct(participation)}`,'☆',satisfaction==null)+
      card('Emploi à six mois',last?'Non observable':employment==null?statusText(g):pct(employment),last?'Diplômés de juillet 2026 : horizon non atteint':g.state==='masked'?'Petits comptes et compléments protégés':`${integer(g.emploi)} / ${integer(g.situations_connues)} situations connues`,'↗',last||employment==null);
    const coverage=rate(s,'connus','inscrits');$('#coverage').textContent=pct(coverage);$('#coverage-bar').style.width=(coverage??0)*100+'%';$('#coverage-description').textContent=s.state==='ok'?`${integer(s.inconnus)} résultats inconnus. Validation parmi les résultats connus : ${pct(rate(s,'validations','connus'))}.`:'Données indisponibles ou protégées.';
    $('#journey-kpis').innerHTML=[['Passage','passages','eligibles_passage'],['Réorientation','reorientations','suivis'],['Sortie documentée','sorties_observees','suivis'],['Situation inconnue','situations_inconnues','suivis']].map(([title,n,d])=>card(title,last?'Non observable':rate(s,n,d)==null?statusText(s):pct(rate(s,n,d)),last?'L’année suivante est hors de la fenêtre':s.state==='ok'?`${integer(s[n])} / ${integer(s[d])} inscriptions de référence`:'Données protégées','↗',last||rate(s,n,d)==null)).join('');
    $('#journey-context').textContent=last?'La cohorte 2025-2026 ne peut pas être suivie en 2026-2027 à cette clôture. Les transitions sont censurées, elles ne valent pas zéro.':`La cohorte de départ ${year} est suivie à l’inscription de l’année suivante. Le passage exclut les niveaux terminaux ; les autres taux utilisent la cohorte suivable complète.`;
    $('#employment-detail').innerHTML=last?'<p class="inline-warning">Devenir des diplômés 2025-2026 : non observable à six mois au 30 septembre 2026.</p>':g.state==='masked'?'<p class="inline-warning">Les données d’insertion de cette année sont masquées dans les exports de diffusion. Les comptes et leurs compléments ont été retirés avant chargement ; un filtre ne peut pas les révéler.</p>':`<p>Participation insertion : ${pct(rate(g,'repondants','sollicites'))}. Emploi parmi situations connues : ${pct(employment)}. Insertion parmi actifs : ${pct(rate(g,'emploi','actifs'))}.</p>`;
    renderChart(formation,name,year);$('#live-region').textContent=`Filtres appliqués : ${year}, ${name}.`;
  }
  function renderChart(formation,name,selected){const years=['2023-2024','2024-2025','2025-2026'];const values=years.map(year=>{const x=aggregate(metric==='satisfaction'?data.survey:data.school,year,formation);return metric==='enrolment'?(x.state==='ok'?x.inscrits:null):metric==='satisfaction'?rate(x,'satisfaits','avis'):rate(x,'validations','inscrits');});
    const isCount=metric==='enrolment',max=isCount?Math.ceil(Math.max(...values.map(v=>v??0))/2000)*2000||2000:1,w=850,h=242,left=52,right=65,top=27,bottom=37,X=i=>left+i*(w-left-right)/2,Y=v=>h-bottom-(h-top-bottom)*v/max;
    let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="chart-svg-title"><title id="chart-svg-title">${metric==='enrolment'?'Effectifs':metric==='satisfaction'?'Satisfaction':'Validation annuelle'} — ${name}, données fictives sur trois années</title>`;
    for(let j=0;j<=4;j++){const value=max*j/4,y=Y(value);svg+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#edf1e9"/><text x="${left-12}" y="${y+4}" text-anchor="end" fill="#8a998b" font-size="10">${isCount?integer(value):Math.round(value*100)+' %'}</text>`;}
    if(values.every(v=>v!=null)){const path=values.map((v,i)=>`${i?'L':'M'}${X(i)},${Y(v)}`).join(' ');svg+=`<path d="${path} L${X(2)},${Y(0)} L${X(0)},${Y(0)} Z" fill="#edf3e7"/><path d="${path}" fill="none" stroke="#347e61" stroke-width="2.5"/>`;}
    values.forEach((v,i)=>{svg+=`<text x="${X(i)}" y="${h-10}" text-anchor="middle" fill="${years[i]===selected?'#276948':'#8a998b'}" font-size="10" font-weight="${years[i]===selected?600:400}">${years[i]}</text>`;if(v!=null)svg+=`<circle cx="${X(i)}" cy="${Y(v)}" r="${years[i]===selected?6:4}" fill="white" stroke="#347e61" stroke-width="2.5"/><text x="${X(i)}" y="${Y(v)-14}" text-anchor="middle" fill="#316949" font-size="11">${isCount?integer(v):pct(v)}</text>`;});svg+='</svg>';$('#chart').innerHTML=svg;
    $('#chart-title').textContent=metric==='enrolment'?'Évolution des effectifs inscrits':metric==='satisfaction'?'Évolution de la satisfaction':'Évolution de la validation annuelle';$('#chart-subtitle').textContent=metric==='enrolment'?'Étudiants distincts dans chaque année universitaire':metric==='satisfaction'?'Notes 4 ou 5 / avis exprimés de 1 à 5':'Validations connues / inscriptions éligibles';$('#chart-legend').textContent=name;
    $('#chart-table').innerHTML=`<table><caption class="sr-only">Valeurs du graphique</caption><thead><tr><th>Année</th><th>Valeur</th></tr></thead><tbody>${years.map((year,i)=>`<tr><td>${year}</td><td>${isCount?integer(values[i]):pct(values[i])}</td></tr>`).join('')}</tbody></table>`;
  }
  $('#year').addEventListener('change',render);$('#formation').addEventListener('change',render);$('#reset').addEventListener('click',()=>{$('#year').value='2025-2026';$('#formation').value='all';render();});
  document.querySelectorAll('[data-metric]').forEach(b=>b.addEventListener('click',()=>{metric=b.dataset.metric;document.querySelectorAll('[data-metric]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));
  render();
})(typeof window==='undefined'?globalThis:window);
